namespace OneSpeech;

/// <summary>Thin audio-input entry points over registered recognizers and VAD pipelines.</summary>
public static partial class Speech
{
    /// <summary>Awaits model I/O and yields final segments from a file in bounded VAD-first chunks, without a whole-file diarization pass. Enumeration owns the decoder and models, including on early disposal. Downloads missing models on first enumeration. Optional language/model select the language and catalog ID; errors follow Transcribe. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static IAsyncEnumerable<Segment> TranscribeStream(string path, string? language = null, string? model = null, CancellationToken cancellationToken = default) =>
        Pipeline.SpeechServices.TranscribeStream(path, language, model, cancellationToken);
    /// <summary>Awaits mono 16 kHz PCM and yields live events. Offline families emit VAD-endpointed finals only; streaming families may emit replacing partials. Owns models and session during enumeration, not the source. Normal end flushes pending speech; early disposal does not. Downloads missing models on first enumeration. Adds endpoint-time CAM++ speaker turns and immutable final-word labels by bounded online clustering (no overlap detection or retrospective merges). Automatic language loads English and Chinese embedders. No capture or devices. Errors follow Transcribe, plus ArgumentException for other PCM formats or chunks over 10 s and CapabilityNotSupportedException for unretained/over-300-s utterances. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static IAsyncEnumerable<LiveEvent> Listen(IAsyncEnumerable<AudioBuffer> source, string? language = null, string? model = null, CancellationToken cancellationToken = default) =>
        Pipeline.SpeechServices.Listen(source, language, model, cancellationToken);
    /// <summary>Aligns written text to a local audio file of at most 60 seconds, downmixed and resampled to mono 16 kHz. By default tries Qwen3-ForcedAligner for its covered language, then CTC; downloads only needed tier-1 models on first use. An explicit model ID selects only that aligner. Unalignable words have null times. Throws typed capability/model/audio errors or IOException for filesystem failures. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static Transcript Align(string path, string text, string? language = null, string? model = null, CancellationToken cancellationToken = default) =>
        Pipeline.SpeechServices.Align(path, text ?? throw new ArgumentNullException(nameof(text)), null, language, model, cancellationToken);
    /// <summary>Aligns an existing document's Words in order, preserving written text and non-timing word fields. File length is limited to 60 seconds. By default tries Qwen3-ForcedAligner for its covered language, then CTC; downloads only needed tier-1 models on first use. An explicit model ID selects only that aligner. Unalignable words keep null times. Errors follow the text overload. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static Transcript Align(string path, Transcript transcript, string? language = null, string? model = null, CancellationToken cancellationToken = default) =>
        Pipeline.SpeechServices.Align(path, null, transcript ?? throw new ArgumentNullException(nameof(transcript)), language ?? transcript.Language, model, cancellationToken);

    /// <summary>Aligns text to caller-owned encoded audio without closing the stream. The stream is asynchronously spooled to a temporary seekable file (512 MiB limit), then decoded to at most 60 seconds of mono 16 kHz PCM. Model acquisition is asynchronous; in-memory inference is synchronous. Throws typed model/audio/capability errors, IOException or OperationCanceledException. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static ValueTask<Transcript> AlignAsync(Stream stream, string text, string? language = null, string? model = null, CancellationToken cancellationToken = default) =>
        Pipeline.SpeechServices.AlignAsync(stream, text ?? throw new ArgumentNullException(nameof(text)), null, language, model, cancellationToken);
    /// <summary>Aligns existing written words to caller-owned encoded audio without re-splitting or closing the stream. Limits, spooling, errors and cancellation follow the text stream overload; non-timing word fields are retained. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static ValueTask<Transcript> AlignAsync(Stream stream, Transcript transcript, string? language = null, string? model = null, CancellationToken cancellationToken = default) =>
        Pipeline.SpeechServices.AlignAsync(stream, null, transcript, language ?? transcript.Language, model, cancellationToken);
    /// <summary>Transcribes a path. Optional language/model select a language tag and catalog ID. Downloads missing tier-1 models on first use. Throws typed model errors on download or integrity failure, UnsupportedAudioException for invalid audio, or OperationCanceledException when canceled. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static Transcript Transcribe(string path, string? language = null, string? model = null, CancellationToken cancellationToken = default) =>
        Pipeline.SpeechServices.Transcribe(path, language, model, cancellationToken);
    /// <summary>Transcribes a readable stream without owning it, asynchronously spooling at most 512 MiB to disk for bounded decoding and replay. Downloads missing tier-1 models on first use. Throws typed model errors on download or integrity failure, UnsupportedAudioException for invalid audio, or OperationCanceledException when canceled. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static ValueTask<Transcript> TranscribeAsync(Stream stream, string? language = null, string? model = null, CancellationToken cancellationToken = default) =>
        Pipeline.SpeechServices.TranscribeAsync(stream, language, model, cancellationToken);
    /// <summary>Detects a language from the first speech chunk of a path. Model selects a catalog ID; language must be null because detection determines it. Downloads missing tier-1 models on first use. Throws typed model errors on download or integrity failure, UnsupportedAudioException for invalid/silent audio, or CapabilityNotSupportedException if language detection is unavailable. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static string DetectLanguage(string path, string? language = null, string? model = null, CancellationToken cancellationToken = default) =>
        Pipeline.SpeechServices.DetectLanguage(path, language, model, cancellationToken);
}
